"""Generate the README screenshots without an OpenWrt router.

The screenshots are rendered from a **sample dataset** (fictional IPs,
hostnames and MACs) so that

* the images can be regenerated by anyone, on any OS, and
* no real network details of the author's home network end up in the repo.

Outputs (SVG + PNG) land in ``docs/``. The PNG conversion is done by
``tools/svg_to_png.py`` because Textual's SVG relies on a webfont that does not
load when the file is embedded in a README.

Usage
-----
    pip install -r requirements-dev.txt
    python tools/make_screenshots.py
"""
from __future__ import annotations

import asyncio
import math
import random
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from core.models import (  # noqa: E402
    CpuInfo,
    DiskInfo,
    IfaceStat,
    LanDevice,
    LogEntry,
    MemoryInfo,
    NetworkInfo,
    PingResult,
    ServiceInfo,
    SystemSnapshot,
)
from tools.svg_to_png import svg_to_png  # noqa: E402

DOCS = ROOT / "docs"

GiB = 1 << 30
MiB = 1 << 20


def _history(points: int, base: float, swing: float, seed: int) -> list[float]:
    """Deterministic, plausible-looking traffic history."""
    rng = random.Random(seed)
    out: list[float] = []
    for i in range(points):
        wave = (math.sin(i / 7.0) + math.sin(i / 2.3)) / 2.0
        out.append(max(0.0, base * (1 + swing * wave) + rng.uniform(0, base * 0.25)))
    return out


