async def render(cols: int, rows: int, stem: str) -> None:
    """Render the dashboard at ``cols``x``rows`` and write SVG + PNG to docs/."""
    from dashboard import OpenWrtDashboard

    snapshot = sample_snapshot()
    app = OpenWrtDashboard()
    # Replace the live collector with the sample dataset.
    app.collector.collect = lambda: snapshot  # type: ignore[method-assign]

    async with app.run_test(size=(cols, rows)) as pilot:
        for _ in range(3):
            app.tick()
            await pilot.pause()
        svg = app.export_screenshot(title=f"OpenWrt Live Dashboard {cols}x{rows}")

    DOCS.mkdir(parents=True, exist_ok=True)
    svg_path = DOCS / f"{stem}.svg"
    svg_path.write_text(svg, encoding="utf-8")

    png_path = svg_to_png(svg, DOCS / f"{stem}.png", scale=2.0)
    print(f"wrote {svg_path.name} and {png_path.name} ({cols}x{rows})")


async def main() -> None:
    await render(100, 37, "screenshot-7in")
    await render(180, 48, "screenshot-wide")


if __name__ == "__main__":
    asyncio.run(main())
